import{_ as e,o as a,c as o,a6 as s}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"收官：验证整条链，也看清离 Clash 还有多远","description":"","frontmatter":{"title":"收官：验证整条链，也看清离 Clash 还有多远"},"headers":[],"relativePath":"proxy-software-course/10-end-to-end-boundary.md","filePath":"proxy-software-course/docs/10-end-to-end-boundary.md"}'),d={name:"proxy-software-course/10-end-to-end-boundary.md"};function r(i,t,n,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="收官-验证整条链-也看清离-clash-还有多远" tabindex="-1">收官：验证整条链，也看清离 Clash 还有多远 <a class="header-anchor" href="#收官-验证整条链-也看清离-clash-还有多远" aria-label="Permalink to &quot;收官：验证整条链，也看清离 Clash 还有多远&quot;">​</a></h1><h2 id="前情-九个承诺-一个拓扑" tabindex="-1">前情：九个承诺，一个拓扑 <a class="header-anchor" href="#前情-九个承诺-一个拓扑" aria-label="Permalink to &quot;前情：九个承诺，一个拓扑&quot;">​</a></h2><p>从第 2 章到第 9 章，每一章都往前递进了一小块能力，也各自留下一句&quot;下一章再兑现&quot;的话。第 9 章最后说，双入口运行时已经可以启动、可以关闭、事件也可以观察到，接下来要用一次完整的本地拓扑核销入口、路由、出站与关闭这条全链路。这一章就来兑现这句话，同时也要诚实地回答另一个问题：这个 mini-proxy 距离一个可以真正拿来用的代理软件，还差多远。</p><h2 id="一次-200-能证明什么-不能证明什么" tabindex="-1">一次 200，能证明什么，不能证明什么 <a class="header-anchor" href="#一次-200-能证明什么-不能证明什么" aria-label="Permalink to &quot;一次 200，能证明什么，不能证明什么&quot;">​</a></h2><p>用 <code>curl</code> 通过这个 mini-proxy 访问一个网站，拿到一个 <code>200 OK</code>，看起来一切正常，值得高兴一下。但这一次成功的请求，只走过了整条数据路径里的一小段：一次简单的直连 HTTP 请求，甚至可能都没经过规则引擎里除了兜底之外的任何一条规则。它没有告诉你 CONNECT 隧道的半关闭处理对不对，没有告诉你规则拒绝在两个入口是否表现一致，更没有告诉你转发到另一个 SOCKS5 上游的链路能不能正常工作。返回一次 200，不代表这些路径都正确，更不代表这个程序已经可以把监听端口暴露公网——这正是本章开头要拆穿的现象。</p><h2 id="用完整拓扑核销全链路-而不是抽查一条路径" tabindex="-1">用完整拓扑核销全链路，而不是抽查一条路径 <a class="header-anchor" href="#用完整拓扑核销全链路-而不是抽查一条路径" aria-label="Permalink to &quot;用完整拓扑核销全链路，而不是抽查一条路径&quot;">​</a></h2><p>要验证&quot;入口、路由、出站、关闭&quot;这条完整链路，需要在一次测试里同时搭起多个角色。一个真实的 HTTP 源站、一个原样回显的 TCP 服务、一个作为上游的 SOCKS5 代理，再加上被测的 mini-proxy 本身，全部只监听 <code>127.0.0.1</code>。<code>tests/10-end-to-end.test.ts</code> 就是这样一份拓扑，配置里同时写了一条 <code>REJECT</code> 域名规则、一条经上游 SOCKS5 转发的 <code>PROXY</code> 域名规则，以及兜底的 <code>DIRECT</code>。</p><p>在运行之前，先针对这五种路径写下你的预测：</p><ol><li>HTTP 入口收到 absolute-form 请求，直连一个真实的 HTTP 源站，响应体会是什么？</li><li>HTTP 入口收到 CONNECT 请求，直连一个 echo 服务，写入的字节会不会原样从另一端读到？</li><li>SOCKS5 入口走完整个握手流程，直连同一个 echo 服务，行为会不会和 HTTP 入口的 CONNECT 一致？</li><li>同一个被 <code>REJECT</code> 规则命中的域名，分别从 HTTP 入口和 SOCKS5 入口发起连接，两边返回的失败信号是不是同一种语义？</li><li>一个命中 <code>PROXY</code> 规则的域名，数据经过上游 SOCKS5 代理转发之后，最终还能不能到达 echo 服务？</li></ol><p>运行命令核对：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> courses/proxy-software-course/companion</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/10-end-to-end.test.ts</span></span></code></pre></div><p>预期本章的五条端到端场景全部通过，分别对应上面五个问题：HTTP absolute-form 请求收到源站响应体 <code>origin-reply:/e2e-check</code>；CONNECT 隧道里写入的 <code>e2e-connect-ping</code> 原样从对端读回；SOCKS5 握手加 CONNECT 之后同样能收发 <code>e2e-socks5-ping</code>；HTTP 入口对 <code>blocked.test</code> 返回 502，SOCKS5 入口对同一个域名返回 <code>CONNECTION_NOT_ALLOWED</code>——两种协议各自的失败表达形式不同，但都对应“规则主动拒绝”这同一种语义；转发到上游 SOCKS5 的链路里，<code>e2e-upstream-chain-ping</code> 依然能完整地经过两跳到达 echo 服务再原样返回。</p><p>再核对一次全量门槛，确认这一章没有让之前任何一块能力回退：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>预期三条命令全部以退出码 0 结束。这四条命令加在一起，才是这一章真正的验收标准：不只是&quot;这一章新写的测试通过&quot;，而是&quot;整个 companion 从第 2 章到现在积累的全部行为，此刻依然全部成立&quot;。</p><h2 id="威胁模型-先问-要防住谁-再谈安全" tabindex="-1">威胁模型：先问&quot;要防住谁&quot;，再谈安全 <a class="header-anchor" href="#威胁模型-先问-要防住谁-再谈安全" aria-label="Permalink to &quot;威胁模型：先问&quot;要防住谁&quot;，再谈安全&quot;">​</a></h2><p><strong>威胁模型</strong>（threat model）指的是在谈&quot;安全不安全&quot;之前，先说清楚三件事：要保护的资产是什么，可能的攻击者是谁，攻击者能从哪个入口下手。没有这三个前提，&quot;安全&quot;是一句空话。对这个 mini-proxy 来说，前面九章从未讨论过这三个问题——所有测试都发生在 <code>127.0.0.1</code>，没有一次考虑过&quot;如果监听地址换成 <code>0.0.0.0</code>，任何能连到这台机器的人会发生什么&quot;。</p><p>这戳穿了第二个误解：<strong>只监听一个端口，并不天然安全</strong>。端口监听在哪个网络接口上（<code>127.0.0.1</code> 还是 <code>0.0.0.0</code>）、谁能连接这个端口、连上之后能做什么，这几件事完全独立于&quot;这个程序有没有 bug&quot;。即便这个 mini-proxy 的每一行代码都完全正确，只要监听地址允许公网访问、又没有任何身份校验，它就已经具备了下一节要讲的那个风险。</p><h2 id="开放代理-任何人都能借它连任意目标" tabindex="-1">开放代理：任何人都能借它连任意目标 <a class="header-anchor" href="#开放代理-任何人都能借它连任意目标" aria-label="Permalink to &quot;开放代理：任何人都能借它连任意目标&quot;">​</a></h2><p><strong>开放代理</strong>（open proxy）指的是一个没有访问控制的代理服务。任何能连上它的人，都能借助它去连接任意目标地址，而不需要证明自己已获准使用。这个 mini-proxy 现在的实现，从代码层面看，正是这个模样——<code>createHttpForwardServer</code> 和 <code>createSocks5Server</code> 都没有校验“是谁在发起这次连接请求”，只要能建立 TCP 连接、按协议格式发请求，就能使用这条转发能力。</p><p>开放代理不只是“被陌生人白嫖流量”这么简单。攻击者可能借一个公网可达的代理去连接原本只有内网才能访问的地址，例如企业内部服务或云主机元数据接口。代理程序因此变成攻击者与受限目标之间的一座桥。这类攻击通常被称为 SSRF（服务端请求伪造）：攻击者不直接连接受限目标，而是借一个有权限访问该目标的服务替自己去连。本课程的规则引擎、DNS 策略用于流量分类和路由，不是访问控制。没有专门的身份校验和网络边界限制之前，不应该把这个 mini-proxy 部署在任何公网可达或能访问敏感内网资源的位置。</p><h2 id="最小权限-只开该开的那一点" tabindex="-1">最小权限：只开该开的那一点 <a class="header-anchor" href="#最小权限-只开该开的那一点" aria-label="Permalink to &quot;最小权限：只开该开的那一点&quot;">​</a></h2><p><strong>最小权限</strong>（least privilege）指的是只开放完成任务所必需的监听范围、目标范围和能力，而不是默认全部打开、出问题了再收窄。前面九章的测试之所以一直坚持只连 <code>127.0.0.1</code>、只用固定的假 resolver、只在配置里显式声明允许的规则，本身就是最小权限原则的一种体现。默认不信任、默认不联网、默认不做任何超出测试目的的事。</p><h2 id="测试全绿-代替不了这些工作" tabindex="-1">测试全绿，代替不了这些工作 <a class="header-anchor" href="#测试全绿-代替不了这些工作" aria-label="Permalink to &quot;测试全绿，代替不了这些工作&quot;">​</a></h2><p>这一章、也是最后一章要戳穿的误解是：<strong>测试全绿，不能替代认证、权限、资源上限和安全审计</strong>。全书写到这里，全部测试断言的都是&quot;给定输入,程序的行为是否符合预期&quot;这一类功能性问题；它们从不检查&quot;陌生人能不能连上来&quot;“一个连接能不能占用无限内存”“会不会有人拿它当跳板做扫描&quot;这类问题，因为这些问题根本不在任何一条测试用例的断言范围内。同样，<strong>能代理一次 HTTP 请求，不等于实现了一个 Clash 类的完整产品</strong>——下面这张表把已经做到的和还没有做的分开列出来。</p><table tabindex="0"><thead><tr><th>能力</th><th>这门课程已实现</th><th>生产级代理通常还需要</th></tr></thead><tbody><tr><td>身份与访问控制</td><td>无——任何能连上的客户端都能使用</td><td>用户认证、IP 白名单、连接数与速率限制</td></tr><tr><td>协议覆盖</td><td>HTTP 正向代理 + CONNECT、SOCKS5（仅 NO AUTH + CONNECT）</td><td>SOCKS5 用户名密码认证、UDP ASSOCIATE、HTTP/2、更多入口协议</td></tr><tr><td>网络层接管</td><td>无 TUN，只处理主动连接到监听端口的流量</td><td>TUN 虚拟网卡把不支持代理设置的流量也接进来（第 1 章提到的机制）</td></tr><tr><td>出站加密</td><td>无——DIRECT/上游 SOCKS5 均为明文 TCP</td><td>出站可选 TLS、支持连接到需要加密的上游节点</td></tr><tr><td>资源治理</td><td>无上限——理论上一个客户端可以占满所有连接</td><td>单连接/单客户端限流、超时回收、内存与文件描述符上限</td></tr><tr><td>可观测性</td><td>结构化事件回调（<code>type</code> + <code>detail</code>）</td><td>完整的日志分级、指标导出、链路追踪</td></tr><tr><td>平台集成</td><td>一个 Node.js 进程 + JSON 配置 + CLI</td><td>系统服务管理、热重载配置、多平台安装包、GUI</td></tr></tbody></table><p>这张表也回应了本章开头的现象：一次成功的 <code>200</code> 只覆盖了&quot;协议覆盖&quot;这一行里极小的一部分，其余每一行都完全没有被这次成功请求触及。</p><h2 id="自查-把风险讲给另一个人听" tabindex="-1">自查：把风险讲给另一个人听 <a class="header-anchor" href="#自查-把风险讲给另一个人听" aria-label="Permalink to &quot;自查：把风险讲给另一个人听&quot;">​</a></h2><details><summary>多台机器之间使用时，最低限度要补哪一项？</summary><p>假设你确实需要在自己完全掌控的两台机器之间转发流量，比如都在你自己的私有网络里，暂时不考虑生产级完整方案。从这门课程学到的机制里，你会优先补上表格里的哪一行？为什么？</p><details><summary>参考答案</summary><p>优先级最高的通常是&quot;身份与访问控制&quot;和&quot;网络层接管&quot;里提到的监听范围问题。至少要把监听地址限制在私有网络能到达、公网无法直接连接的范围内，避免成为开放代理；如果连接确实需要经过不完全可信的网络，还需要补上出站加密，否则内容以明文传输。资源治理和可观测性也重要，但如果访问控制这一步没有做，其他改进都是在一个本来就不该被任意连接的系统上做优化，意义有限。</p></details></details><details><summary>为什么&quot;测试全绿&quot;不能写进安全审计报告？</summary><p>如果有人说&quot;这个 mini-proxy 的 84 个测试全部通过，所以它是安全的&quot;，这句话的推理漏洞在哪里？</p><details><summary>参考答案</summary><p>漏洞在于&quot;测试通过&quot;和&quot;安全&quot;回答的是两个不同的问题。测试断言的是&quot;给定这些输入，程序按预期方式响应&quot;，覆盖的是功能正确性；而安全审计要回答的是&quot;面对没有被写进任何测试用例的恶意输入或恶意使用方式，系统的边界在哪里&quot;。一个功能完全正确的程序，仍然可能是一个开放代理、仍然可能没有资源上限、仍然可能被用作 SSRF 的跳板——这些问题的答案跟&quot;测试是不是全绿&quot;没有任何逻辑上的因果关系。</p></details></details><h2 id="边界重申-这门课程到此为止的范围" tabindex="-1">边界重申：这门课程到此为止的范围 <a class="header-anchor" href="#边界重申-这门课程到此为止的范围" aria-label="Permalink to &quot;边界重申：这门课程到此为止的范围&quot;">​</a></h2><p>回到第 1 章立下的边界：这套 mini-proxy 从设计之初就只面向自有或者已经明确获得授权的环境，所有自动化验证也一直只连接 <code>127.0.0.1</code>。到这一章为止，它已经能完整演示 HTTP 正向代理、CONNECT 隧道、SOCKS5 服务端、规则路由、DNS 策略、出站适配器和双入口运行时这一整条 Clash 类工具的数据面主线。这是这门课程承诺教会你的全部内容。它没有实现，也不打算在这门课程范围内实现认证、UDP、TUN、加密出站、资源上限、访问控制或任何平台集成。这些是一个可以安全对外提供服务的产品还需要补齐的部分，本课程不提供把它们组装成可公网部署服务的指引。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-9.3.6" target="_blank" rel="noreferrer">RFC 9110 的 CONNECT 安全说明</a>警告不受限制的隧道会带来显著风险。该规范建议把目标限制在已知安全的端口。<a href="https://www.rfc-editor.org/rfc/rfc1928.html" target="_blank" rel="noreferrer">RFC 1928</a>定义了方法协商，但本课选择的 NO AUTH 本身不提供身份校验。这也是为什么本章把“能转发流量”和“能安全地对外提供代理服务”当作两件必须分开讨论的事。</p><h2 id="回到开头的那次-200" tabindex="-1">回到开头的那次 200 <a class="header-anchor" href="#回到开头的那次-200" aria-label="Permalink to &quot;回到开头的那次 200&quot;">​</a></h2><p>现在可以完整回答开头的问题了：<code>curl</code> 拿到的一次 <code>200</code>，只证明了这一次具体请求从入口到出站的某一条路径确实走通了；它没有验证半关闭是否正确、两个入口的规则是否一致、转发到上游代理的链路是否完整——这些都需要像本章这样搭一次完整拓扑才能核实。它更不能作为&quot;可以把这个端口暴露到公网&quot;的证据：能不能对外提供服务，取决于身份校验、访问范围、资源治理这些全书都没有涉及的问题，跟功能是否正确是两回事。</p><p>三段模型里的入口、路由、出站，到这一章为止，已经全部从一句话变成了可以运行、可以验证的代码，一共由 84 项测试从不同角度守护着。这是这门课程能带你走到的地方；再往前一步，走向一个真正可以安全对外提供服务的代理程序，是另一段旅程了。</p>`,35)])])}const q=e(d,[["render",r]]);export{u as __pageData,q as default};
